#!/usr/bin/env node
// Regenerates docs/assets/headroom-demo.gif from docs/assets/headroom-demo.svg
// (itself generated by scripts/render-demo-animated.mjs from the real CLI
// against a mock home). The SVG animation is plain CSS, so each frame is the
// SVG with every animation paused at one point of the loop, screenshotted by
// headless Chrome, then joined by ffmpeg into a looping GIF.
//
// Needs Google Chrome (or CHROME=/path/to/chrome) and ffmpeg on PATH.
// Usage: node scripts/render-demo-gif.mjs
import { spawnSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const svgPath = join(root, "docs", "assets", "headroom-demo.svg");
const out = join(root, "docs", "assets", "headroom-demo.gif");
const FPS = 8;
const chrome = process.env.CHROME ?? ["/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", "google-chrome", "chromium"].find((path) => !path.startsWith("/") || existsSync(path));
const svg = readFileSync(svgPath, "utf8");
const width = Number(/<svg[^>]* width="(\d+)"/.exec(svg)?.[1]);
const height = Number(/<svg[^>]* height="(\d+)"/.exec(svg)?.[1]);
const total = Number(/animation:\w+ ([\d.]+)s infinite/.exec(svg)?.[1]);
if (!width || !height || !total) throw new Error("cannot read the size or loop length from the SVG");

const dir = mkdtempSync(join(tmpdir(), "headroom-gif-"));
try {
  const frames = Math.round(total * FPS);
  for (let i = 0; i < frames; i++) {
    const frozen = svg.replace("</style>", `*{animation-play-state:paused!important;animation-delay:-${(i / FPS).toFixed(3)}s!important}</style>`);
    const name = String(i).padStart(4, "0");
    writeFileSync(join(dir, `${name}.svg`), frozen);
    const args = ["--headless=new", "--disable-gpu", "--hide-scrollbars", "--force-device-scale-factor=1", `--window-size=${width},${height}`, `--screenshot=${join(dir, `${name}.png`)}`, join(dir, `${name}.svg`)];
    // Headless Chrome occasionally exits non-zero on a frame; retry before giving up.
    let ok = false;
    for (let attempt = 0; attempt < 3 && !ok; attempt++) ok = spawnSync(chrome, args, { stdio: "ignore", timeout: 30_000 }).status === 0 && existsSync(join(dir, `${name}.png`));
    if (!ok) throw new Error(`Chrome failed on frame ${i}`);
  }
  const filter = "split[a][b];[a]palettegen=max_colors=32:stats_mode=diff[p];[b][p]paletteuse=dither=none";
  const gif = spawnSync("ffmpeg", ["-y", "-loglevel", "error", "-framerate", String(FPS), "-i", join(dir, "%04d.png"), "-vf", filter, "-loop", "0", out], { stdio: "inherit" });
  if (gif.status !== 0) throw new Error("ffmpeg failed");
  console.log(out);
} finally {
  rmSync(dir, { recursive: true, force: true });
}
